def run_paper_demo(system: str = "qubit",
                   method: str = "dsatur",
                   operator_count: Optional[int] = None,
                   operator_selection: str = "all",
                   target_operator_labels: Optional[Sequence[str]] = None,
                   n_qubits: int = 2,
                   n_qutrits: int = 1,
                   local_dim: int = 3,
                   n_qudits: int = 1,
                   seed: int = 250,
                   dsatur_attempts: int = 25,
                   gnn_epochs: int = 150,
                   verbose: bool = True) -> Dict[str, Any]:
    """
    Single demo entry point.

    system options:
      - 'qubit'  : original Pauli tomography-design code; returns commuting sets and A.
      - 'qutrit' : original homogeneous qudit benchmark with d=3.
      - 'qudit'  : original homogeneous qudit benchmark with selected local_dim.
      - 'hybrid' : original heterogeneous qubit-qutrit benchmark.
    """
    s = system.lower().strip()
    if s == "qubit":
        return run_qubit_demo(
            n_qubits=n_qubits,
            method=method,
            operator_count=operator_count,
            operator_selection=operator_selection,
            target_operator_labels=target_operator_labels,
            seed=seed,
            dsatur_attempts=dsatur_attempts,
            verbose=verbose,
        )
    if s == "qutrit":
        return run_qutrit_demo(
            n_qutrits=n_qutrits,
            operator_count=8 if operator_count is None else int(operator_count),
            method=method,
            seed=seed,
            gnn_epochs=gnn_epochs,
            verbose=verbose,
        )
    if s == "qudit":
        return run_qudit_demo(
            local_dim=local_dim,
            n_qudits=n_qudits,
            operator_count=8 if operator_count is None else int(operator_count),
            method=method,
            seed=seed,
            gnn_epochs=gnn_epochs,
            verbose=verbose,
        )
    if s == "hybrid":
        return run_hybrid_demo(
            n_qubits=n_qubits,
            n_qutrits=n_qutrits,
            operator_count=20 if operator_count is None else int(operator_count),
            method=method,
            seed=seed,
            gnn_epochs=gnn_epochs,
            verbose=verbose,
        )
    raise ValueError("system must be one of: 'qubit', 'qutrit', 'qudit', 'hybrid'.")


def print_demo_summary(result: Dict[str, Any]) -> None:
    """Pretty summary for the tutorial notebook."""
    if result.get("method") == "all" and "runs" in result:
        print("=== Multi-method summary ===")
        for name, sub in result["runs"].items():
            if "error" in sub:
                print(f"{name:10s} ERROR: {sub['error']}")
            else:
                print(f"{name:10s} settings={len(sub.get('commuting_sets', []))} A_shape={sub.get('A_shape')}")
        return

    system = result.get("system")
    print("=== Demo Summary ===")
    print("System:", system)
    print("Method:", result.get("method"))

    if system == "qubit":
        print("Number of selected operators:", result.get("operator_count"))
        print("Number of measurement settings:", len(result.get("commuting_sets", [])))
        print("A shape:", result.get("A_shape"))
        print("\nCommuting measurement settings:")
        for i, labels in enumerate(result.get("commuting_set_labels", []), start=1):
            print(f"  S{i} = {labels}")
    else:
        raw = result.get("raw_result")
        print("Operator count:", result.get("operator_count"))
        print("Raw result:")
        print(raw)
